const consumeDots = (k: number): { j: number; relative: number } => {
    let relative = 0;
    let j = k;
    while (isOp(j, '.')) {
      relative++;
      j++;
    }
    return { j, relative };
  };

const consumeModule = (k: number): { parts: string[]; j: number } => {
    const parts: string[] = [];
    let j = k;
    while (isName(j)) {
      parts.push(tokens[j]!.value);
      j++;
      if (isOp(j, '.')) {
        j++;
        continue;
      }
      break;
    }
    return { parts, j };
  };

